const body = $input.item.json.body || $input.item.json || {};
const code = body.code || body.message || '';
const language = body.language || 'auto-detect';
const level = body.level || 'intermediate';

const systemPrompt = `You are HomeBot Code Explainer. Break down code into clear, understandable explanations.

Explanation level: ${level}
Language hint: ${language}

Format your response as:
## Code Analysis
**Language:** [detected language]
**Purpose:** [one-line summary]

### Line-by-Line Breakdown
Explain what each significant section does.

### Key Concepts Used
List and briefly explain programming concepts (e.g., recursion, closures, async/await).

### Potential Improvements
Suggest 2-3 improvements if applicable.

Use code blocks for any code references. Be educational and encouraging.`;

return {
  json: {
    model: 'qwen2.5:7b',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `Explain this code:

${code}` }
    ],
    stream: false
  }
};

const ollamaRes = $input.item.json;
const content = ollamaRes.message?.content || ollamaRes.response || 'Unable to analyze code';
return {
  json: {
    output: content,
    data: { assistant: { role: 'assistant', content } }
  }
};
